/**
 * Analytics entry point — FR-22.
 *
 * One `track()` wrapper applies the R6 filter and merges the FR-23 dimensions,
 * so no call site ever assembles a payload by hand.
 */

import { config } from "@/config";
import type { Analytics } from "@/lib/types";
import { commonContext } from "./context";
import { isBlockedTraffic } from "./filter";
import { consoleSink, createAnalytics, type Sink } from "./port";

const SINKS: Record<string, Sink> = {
  console: consoleSink,
  // Q5 — add the chosen provider here; flip NEXT_PUBLIC_ANALYTICS_PROVIDER.
};

let analytics: Analytics | null = null;

export function getAnalytics(): Analytics {
  analytics ??= createAnalytics({
    sink: SINKS[config.NEXT_PUBLIC_ANALYTICS_PROVIDER] ?? consoleSink,
    context: commonContext,
    blocked: isBlockedTraffic,
  });
  return analytics;
}
