/**
 * Session identity + the `qr_scan` once-guard — C-3, FR-23.
 *
 * The guard is the single most important line of G1 measurement: if `qr_scan`
 * fires more than once per session the denominator inflates and the reported
 * metric is wrong.
 */

import type { StorageAdapter } from "./storage";
import type { DeviceType } from "./types";

export const SESSION_ID_KEY = "session_id";
export const QR_SCAN_FIRED_KEY = "qr_scan_fired";

/** Random ID without `randomUUID` (which needs a secure context, NFR-8). */
export function newId(): string {
  const buffer = new Uint32Array(4);
  globalThis.crypto.getRandomValues(buffer);
  return Array.from(buffer, (n) => n.toString(36).padStart(7, "0")).join("");
}

export function createSession(deps: { storage: StorageAdapter }) {
  const { storage } = deps;

  function getSessionId(): string {
    let id = storage.sessionGet(SESSION_ID_KEY);
    if (!id) {
      id = newId();
      storage.sessionSet(SESSION_ID_KEY, id);
    }
    return id;
  }

  /**
   * Returns `true` exactly once per session. Callers must additionally check
   * QR context first (C-3): a returning visitor on `/` has no `qr_scan`.
   */
  function claimQrScan(): boolean {
    if (storage.sessionGet(QR_SCAN_FIRED_KEY) === "1") return false;
    storage.sessionSet(QR_SCAN_FIRED_KEY, "1");
    return true;
  }

  return { getSessionId, claimQrScan };
}

export type SessionController = ReturnType<typeof createSession>;

/**
 * Deliberately coarse — only used for analytics dimension `device_type` and for
 * deciding desktop-vs-mobile handoff behaviour (FR-23, FR-13).
 */
export function getDeviceType(userAgent: string | null | undefined): DeviceType {
  const ua = userAgent ?? "";
  if (/(iPad|Tablet|PlayBook|Silk)/i.test(ua)) return "tablet";
  if (/Android(?![\s\S]*Mobile)/i.test(ua)) return "tablet";
  if (
    /(Mobi|Android|iPhone|iPod|IEMobile|Opera Mini|BlackBerry|Windows Phone)/i.test(
      ua,
    )
  ) {
    return "mobile";
  }
  return "desktop";
}
